 import React, { useState } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { useNavigate } from 'react-router-dom'
import { 
  LogOut, 
  User, 
  Bell, 
  Shield, 
  Globe, 
  ChevronRight,
  Sun,
  Lock,
  HelpCircle,
  Moon,
  Smartphone,
  Users,
  Award,
  ChevronLeft
} from 'lucide-react'

export default function Settings() {
    const { user, profile, signOut } = useAuth()
    const navigate = useNavigate()

    const handleSignOut = async () => {
        if (window.confirm('Are you sure you want to sign out?')) {
            await signOut()
            navigate('/login')
        }
    }

    const settingsSections = [
        {
            title: 'Account',
            items: [
                { 
                    icon: User, 
                    label: 'Edit Profile', 
                    onClick: () => navigate('/profile'),
                    description: profile?.full_name || profile?.username || 'Set up your profile'
                },
                { 
                    icon: Bell, 
                    label: 'Notifications', 
                    onClick: () => navigate('/notifications'),
                    description: 'Manage your notifications'
                },
                { 
                    icon: Lock, 
                    label: 'Privacy', 
                    onClick: () => {},
                    description: 'Control your privacy settings'
                },
            ]
        },
        {
            title: 'Preferences',
            items: [
                { 
                    icon: Sun, 
                    label: 'Appearance', 
                    onClick: () => navigate('/settings/appearance'),  // Updated
                    description: 'Light / Dark mode'
                },
                { 
                    icon: Globe, 
                    label: 'Language', 
                    onClick: () => navigate('/settings/language'),  // Updated
                    description: 'Change your language'
                },
            ]
        },
        {
            title: 'Support',
            items: [
                { 
                    icon: HelpCircle, 
                    label: 'Help & Feedback', 
                    onClick: () => {},
                    description: 'Get help or send feedback'
                },
                { 
                    icon: Shield, 
                    label: 'Privacy Policy', 
                    onClick: () => {},
                    description: 'Read our privacy policy'
                },
                { 
                    icon: Smartphone, 
                    label: 'App Version', 
                    onClick: () => {},
                    description: 'v1.0.0'
                },
            ]
        }
    ]

    return (
        <div className="min-h-screen bg-gray-50 px-4 py-6 pb-20">
            <div className="flex items-center gap-3 mb-6">
                <button 
                    onClick={() => navigate(-1)}
                    className="p-2 hover:bg-gray-200 rounded-lg transition"
                >
                    <ChevronLeft size={24} className="text-gray-700" />
                </button>
                <h1 className="text-2xl font-bold text-gray-800">Settings</h1>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-6 flex items-center gap-4">
                <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center text-gray-600 font-bold text-lg">
                    {profile?.username?.[0]?.toUpperCase() || user?.email?.[0]?.toUpperCase() || 'U'}
                </div>
                <div>
                    <p className="font-semibold text-gray-800">{profile?.full_name || profile?.username || 'User'}</p>
                    <p className="text-sm text-gray-400">{user?.email}</p>
                </div>
                <button 
                    onClick={() => navigate('/profile')}
                    className="ml-auto text-sm text-gray-500 hover:text-gray-700"
                >
                    Edit
                </button>
            </div>

            {settingsSections.map((section) => (
                <div key={section.title} className="mb-6">
                    <h2 className="text-sm font-medium text-gray-500 uppercase tracking-wider mb-2 px-2">
                        {section.title}
                    </h2>
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        {section.items.map((item, index) => {
                            const Icon = item.icon
                            return (
                                <button
                                    key={index}
                                    onClick={item.onClick}
                                    className={`w-full flex items-center justify-between px-4 py-3 hover:bg-gray-50 transition ${
                                        index !== section.items.length - 1 ? 'border-b border-gray-100' : ''
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <Icon size={18} className="text-gray-500" />
                                        <div className="text-left">
                                            <span className="text-gray-700 font-medium">{item.label}</span>
                                            {item.description && (
                                                <p className="text-xs text-gray-400">{item.description}</p>
                                            )}
                                        </div>
                                    </div>
                                    <ChevronRight size={18} className="text-gray-400" />
                                </button>
                            )
                        })}
                    </div>
                </div>
            ))}

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-6">
                <div className="grid grid-cols-3 gap-4 text-center">
                    <div>
                        <p className="text-2xl font-bold text-gray-800">{profile?.predictions_count || 0}</p>
                        <p className="text-xs text-gray-400">Predictions</p>
                    </div>
                    <div>
                        <p className="text-2xl font-bold text-gray-800">{profile?.points || 0}</p>
                        <p className="text-xs text-gray-400">Points</p>
                    </div>
                    <div>
                        <p className="text-2xl font-bold text-gray-800">{profile?.accuracy || 0}%</p>
                        <p className="text-xs text-gray-400">Accuracy</p>
                    </div>
                </div>
            </div>

            <button
                onClick={handleSignOut}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-red-50 text-red-600 rounded-xl font-medium hover:bg-red-100 transition"
            >
                <LogOut size={18} />
                Sign Out
            </button>

            <div className="text-center mt-6">
                <p className="text-xs text-gray-400">PredictFC v1.0.0</p>
            </div>
        </div>
    )
}
